<script lang="ts">
import type { Snippet } from 'svelte';
import { untrack, tick, onMount, onDestroy } from 'svelte';
import type { TutorialPanelContract } from '@unofficial-krds/contracts';
import { owned, control, resetField, ignoredKey } from './catalog-state.svelte.js';
let p: TutorialPanelContract & { help?:Snippet; openerId?:string; startActionPresent?:boolean; delegateEntry?:boolean; id?:string } = $props();
import PanelShell from './PanelShell.svelte';let narrow=$state(untrack(()=>typeof matchMedia==='function'&&matchMedia('(max-width:767px)').matches));const open=control(()=>p.open,untrack(()=>p.defaultOpen),untrack(()=>!narrow),open=>p.onOpenChange?.({open}));const panel=control<'help'|'tutorial'>(()=>p.activePanel,untrack(()=>p.defaultActivePanel),'tutorial',value=>p.onActivePanelChange?.({value}));const running=control(()=>p.running,untrack(()=>p.defaultRunning),false,()=>{});const uid=$props.id();const openerId=$derived(p.openerId??`${uid}-opener`);onMount(()=>{const media=matchMedia('(max-width:767px)');const change=()=>narrow=media.matches;change();media.addEventListener('change',change);return()=>media.removeEventListener('change',change);});const selected=$derived(p.tasks.find(task=>task.id===p.activeTaskId&&task.steps.length)||p.tasks.find(task=>task.steps.length));function start(){const task=selected;if(running.value||!task)return;const step=task.steps.find(step=>step.id===p.activeStepId)??task.steps[0];running.request(true);p.onStart?.({taskId:task.id,stepId:step.id});}function stop(){p.onStop?.({reason:'stop',running:false,returnTo:{panel:'tutorial',open:true,startActionId:p.startActionId}});}
// Disclosure starts from and re-syncs to the host-committed activeTaskId (never auto-expanding a fallback task); a local fold is kept across passive task-data updates. `selected` only chooses Start's target.
let expanded=$state<string|null>(untrack(()=>p.activeTaskId??null));const committedTaskId=$derived(p.activeTaskId??null);$effect(()=>{expanded=committedTaskId;});
// Task view (frozen component_08_02 body state b) replaces the overview only when the host has committed a task and one of its steps.
const viewTask=$derived(p.activeStepId!=null?p.tasks.find(task=>task.id===p.activeTaskId):undefined);const visibleTasks=$derived(viewTask?[viewTask]:p.tasks);
</script>
<button id={openerId} type="button" {...owned('tutorial-panel','opener')} aria-expanded={open.value} onclick={()=>open.request(!open.value)}>튜토리얼 열기</button><PanelShell id={p.id??uid} labelledby={`${uid}-title`} componentId="tutorial-panel" states={running.value?'open running':'open idle'} open={open.value} {narrow} title="따라하기" returnFocusId={openerId} fallbackFocusId={p.fallbackFocusId} delegateEntry={p.delegateEntry} initialFocusId={!running.value&&panel.value==='tutorial'?p.startActionId:undefined} onClose={()=>open.request(false)}><div {...owned('tutorial-panel','header')}><h2 id={`${uid}-title`} {...owned('tutorial-panel','title')}>따라하기</h2><button type="button" {...owned('tutorial-panel','close')} onclick={()=>open.request(false)}>튜토리얼 닫기</button></div><div {...owned('tutorial-panel','tabs')} role="tablist" aria-label="지원 패널"><button id={`${uid}-help-tab`} {...owned('tutorial-panel','tab',panel.value==='help'&&'selected')} type="button" role="tab" aria-controls={`${uid}-help`} aria-selected={panel.value==='help'} onclick={()=>panel.request('help')}>도움말</button><button id={`${uid}-tutorial-tab`} {...owned('tutorial-panel','tab',panel.value==='tutorial'&&'selected')} type="button" role="tab" aria-controls={`${uid}-tutorial`} aria-selected={panel.value==='tutorial'} onclick={()=>panel.request('tutorial')}>튜토리얼</button></div><section id={`${uid}-help`} role="tabpanel" aria-labelledby={`${uid}-help-tab`} hidden={panel.value!=='help'}>{#if p.help}{@render p.help()}{:else}<p>도움말을 확인하세요.</p>{/if}</section><section id={`${uid}-tutorial`} role="tabpanel" aria-labelledby={`${uid}-tutorial-tab`} hidden={panel.value!=='tutorial'}>{#if p.startActionPresent!==false}<button id={p.startActionId} {...owned('tutorial-panel','start')} type="button" disabled={running.value||!selected?.steps.length} onclick={start}>따라하기 시작</button>{/if}{#if viewTask}<button type="button" {...owned('tutorial-panel','back')} onclick={()=>p.onTaskChange?.({id:null})}>작업 목록</button>{/if}<ul {...owned('tutorial-panel','task-list')}>{#each visibleTasks as task(task.id)}<li {...owned('tutorial-panel','task')}><details open={expanded===task.id}><summary {...owned('tutorial-panel','task-toggle')} onclick={event=>{event.preventDefault();expanded=expanded===task.id?null:task.id;if(expanded&&task.id!==p.activeTaskId)p.onTaskChange?.({id:task.id});}}>{task.title}</summary><ol {...owned('tutorial-panel','step-list')}>{#each task.steps as step}<li data-krds-state={step.id===p.activeStepId?'active-step':''}><button {...owned('tutorial-panel','step',step.id===p.activeStepId&&'current')} aria-current={step.id===p.activeStepId?'step':undefined} type="button" onclick={()=>{if(step.id!==p.activeStepId)p.onStepChange?.({id:step.id});}}>{step.title}</button><p>{step.instruction}</p></li>{/each}</ol></details></li>{/each}</ul></section>{#if running.value}<button type="button" {...owned('tutorial-panel','stop')} onclick={stop}>따라하기 중지</button>{/if}</PanelShell>
